AccountKey key = new AccountKey("ACC-101");
map.put(key, "Active");

// Mutating a field changes key.hashCode()!
key.setAccountId("ACC-999");

System.out.println(map.get(key)); // null!
System.out.println(map.size());   // 1 (orphaned entry)

